t.script:
                var D={regions:[],hubs:[],lanes:[],services:[],deps:[]},map=null,markers=[],lines=[],oid=null,did=null;
                function init(){
                    map=new google.maps.Map(document.getElementById('wwg_map_v2'),{center:{lat:44.8,lng:-77.0},zoom:7,mapTypeControl:false,streetViewControl:false});
                    var x=new XMLHttpRequest();
                    x.open('POST','/logistics/where-we-go/data',true);
                    x.setRequestHeader('Content-Type','application/json');
                    x.onload=function(){if(x.status===200){var j=JSON.parse(x.responseText);if(j.result)j=j.result;D.regions=j.regions||[];D.hubs=j.hubs||[];D.lanes=j.lanes||[];D.services=j.services||[];D.deps=j.departures||[];pop();drawMarkers();}};
                    x.send('{"jsonrpc":"2.0","method":"call","params":{},"id":1}');
                }
                function pop(){
                    var o=document.getElementById('wwg_origin_v2');o.innerHTML='-- Select Pickup --';
                    D.regions.sort(function(a,b){return(a.display_number||a.id)-(b.display_number||b.id)}).forEach(function(r){
                        o.innerHTML+=''+(r.display_number||r.id)+'. '+r.name+' - '+(r.main_city||'')+'';
                    });
                    o.onchange=function(){oid=parseInt(this.value)||null;updateDests();drawRoute();};
                    document.getElementById('wwg_dest_v2').onchange=function(){did=parseInt(this.value)||null;drawRoute();};
                    document.getElementById('wwg_reset_v2').onclick=function(){oid=null;did=null;o.value='';document.getElementById('wwg_dest_v2').value='';document.getElementById('wwg_dest_v2').innerHTML='-- First select pickup --';document.getElementById('wwg_result_v2').innerHTML='
Select origin and destination to see route details.';drawRoute();};
                }
                function updateDests(){var d=document.getElementById('wwg_dest_v2');d.innerHTML='-- Select Delivery --';if(!oid)return;var ids=new Set();D.lanes.forEach(function(l){if(l.origin_id===oid)ids.add(l.dest_id)});D.regions.forEach(function(r){if(ids.has(r.id))d.innerHTML+=''+(r.display_number||r.id)+'. '+r.name+' - '+(r.main_city||'')+'';});}
                function drawMarkers(){markers.forEach(function(m){m.setMap(null)});markers=[];D.regions.forEach(function(r){var m=new google.maps.Marker({position:{lat:r.lat||44,lng:r.lng||-78},map:map,label:{text:String(r.display_number||r.id),color:'#fff',fontSize:'11px',fontWeight:'bold'},title:r.name,icon:{path:google.maps.SymbolPath.CIRCLE,scale:12,fillColor:'#1a73e8',fillOpacity:0.9,strokeColor:'#fff',strokeWeight:2}});m.addListener('click',function(){document.getElementById('wwg_origin_v2').value=r.id;oid=r.id;updateDests();drawRoute();});markers.push(m)});D.hubs.forEach(function(h){var m=new google.maps.Marker({position:{lat:h.lat||43.65,lng:h.lng||-79.66},map:map,icon:{path:google.maps.SymbolPath.CIRCLE,scale:8,fillColor:'#ea4335',fillOpacity:0.9,strokeColor:'#fff',strokeWeight:2},title:h.public_name||h.name,label:{text:'HUB',color:'#ea4335',fontSize:'8px',fontWeight:'bold'}});markers.push(m)});}
                function drawRoute(){lines.forEach(function(l){l.setMap(null)});lines=[];var r=document.getElementById('wwg_result_v2');if(!oid||!did){r.innerHTML='
Select origin and destination to see route details.';return}var o=D.regions.find(function(rr){return rr.id===oid});var d=D.regions.find(function(rr){return rr.id===did});if(!o||!d)return;var lane=D.lanes.find(function(l){return l.origin_id===oid&&l.dest_id===did});var direct=lane&&lane.direct_allowed;var hub=D.hubs.find(function(h){return h.is_default})||D.hubs[0];var path=[];if(direct)path=[{lat:o.lat||44,lng:o.lng||-78},{lat:d.lat||44,lng:d.lng||-78}];else if(hub)path=[{lat:o.lat||44,lng:o.lng||-78},{lat:hub.lat||43.65,lng:hub.lng||-79.66},{lat:d.lat||44,lng:d.lng||-78}];if(path.length>=2){var line=new google.maps.Polyline({path:path,map:map,strokeColor:direct?'#34a853':'#1a73e8',strokeOpacity:0.7,strokeWeight:3,icons:[{icon:{path:google.maps.SymbolPath.FORWARD_CLOSED_ARROW,scale:3},offset:'100%'}]});lines.push(line);var b=new google.maps.LatLngBounds();path.forEach(function(p){b.extend(p)});map.fitBounds(b)}var svc=D.services.find(function(s){if(!s.stops||s.stops.length<2)return false;var ids=s.stops.map(function(st){return st.region_id});return ids.indexOf(oid)>=0&&ids.indexOf(did)>=0});var dep=svc?D.deps.find(function(dd){return dd.corridor_id===svc.id}):null;var rt=direct?'Direct Service':(hub?'Via '+hub.public_name:'Via Hub');var pd=svc?(svc.weekday||'Scheduled'):'Contact us';var dd=dep?dep.date:'Next available';r.innerHTML='
'+rt+'
Pickup: '+o.name+' - '+(o.main_city||'')+'
Delivery: '+d.name+' - '+(d.main_city||'')+'
Service Day: '+pd+'
Earliest Delivery: '+dd+''+(svc?'
Weekly Service: '+svc.name+'':'')+'
Frequency: Weekly'+(lane?'
Road Distance: '+lane.road_km+' km':'')+'
Check Price';}
                if(typeof google!=='undefined'&&google.maps){init()}else{window.initMap=init}
